	private static readonly long RUN_TIMEOUT_MS = 5000;
	private static readonly long RETRY_MS = 500;

	record LldbAndTrace(LldbAndConnection conn, ManagedDomainObject<Trace> mdo) : AutoCloseable {
		public void execute(string cmd) {
			conn.execute(cmd);
		}

		public string executeCapture(string cmd) {
			return conn.executeCapture(cmd);
		}

		public void success() {
			conn.success();
		}

		/* @Override */
		public void close()
    {
			Exception toThrow = null;
			try {
				conn.close();
			}
			catch (Exception e) {
				toThrow = e;
			}
			try {
				mdo.close();
			}
			catch (Exception e) {
				toThrow = e;
			}
			if (toThrow != null) {
				throw toThrow;
			}
		}
	}

	/* @SuppressWarnings("resource") */
	protected LldbAndTrace startAndSyncLldb()
    {
		LldbAndConnection conn = startAndConnectLldb();
		try {
			conn.execute("ghidra trace start");
			ManagedDomainObject<Trace> mdo = waitTrace("/New Traces/lldb/noname");
			tb = new ToyDBTraceBuilder(mdo.get());
			return new LldbAndTrace(conn, mdo);
		}
		catch (Exception e) {
			conn.close();
			throw e;
		}
	}

	protected long lastSnap(LldbAndTrace conn) {
		return conn.conn.connection().getLastSnapshot(tb.trace);
	}

	// TODO: This passes if you single-step through it but fails on some transactional stuff if run
	//@Test
	public void testOnNewThread()
    {
		string specimen = getSpecimenNewThreadAndExit();
		using (LldbAndTrace conn = startAndSyncLldb())
{

			start(conn, "%s".formatted(specimen));
			conn.execute("break set -n work");
			waitForPass(() => {
				TraceObject proc = tb.objAny0("Processes[]");
				assertNotNull(proc);
				assertEquals("STOPPED", tb.objValue(proc, lastSnap(conn), "_state"));
			}, RUN_TIMEOUT_MS, RETRY_MS);

			txPut(conn, "threads");
			waitForPass(() => assertEquals(1,
				tb.objValues(lastSnap(conn), "Processes[].Threads[]").size()),
				RUN_TIMEOUT_MS, RETRY_MS);

			conn.execute("continue");
			waitStopped(conn.conn);
			txPut(conn, "threads");
			waitForPass(() => assertEquals(2,
				tb.objValues(lastSnap(conn), "Processes[].Threads[]").size()),
				RUN_TIMEOUT_MS, RETRY_MS);
			conn.success();
		}
	}

